package vn.vinhkhang.thuchi;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.util.*;import java.io.*;import jakarta.servlet.http.HttpServletRequest;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.*;
class ExcelExportTest {
 @Test void preservesTypesAndExcludesCanceledVouchers()throws Exception {var api=mock(Api.class);var request=mock(HttpServletRequest.class);var export=new ExcelExport(api);var body=new HashMap<String,Object>();body.put("rows",List.of(List.of("STT","Ngày","Số tài khoản","Nội dung","Số tiền","Trạng thái"),List.of(1,"2026-10-08","000123456789","=HYPERLINK(\"https://example.com\")",10000000,"Đã ghi sổ"),List.of(2,"2026-10-09","000123456789","Hủy",9000000,"Đã hủy"),List.of(3,"2026-10-10","000123456789","Hoàn",-1000000,"Đã ghi sổ")));body.put("totalColumns",List.of(4));try(var w=new XSSFWorkbook(new ByteArrayInputStream(export.export(body,request).getBody()))){var s=w.getSheetAt(0);assertEquals(CellType.STRING,s.getRow(5).getCell(2).getCellType());assertEquals("000123456789",s.getRow(5).getCell(2).getStringCellValue());assertEquals(CellType.STRING,s.getRow(5).getCell(3).getCellType());assertTrue(DateUtil.isCellDateFormatted(s.getRow(5).getCell(1)));assertEquals(9000000,s.getRow(8).getCell(4).getNumericCellValue());assertEquals(BorderStyle.THIN,s.getRow(6).getCell(4).getCellStyle().getBorderBottom());verify(api).auth(request,false);}}
 @Test void rejectsMalformedRows() {var export=new ExcelExport(mock(Api.class));assertThrows(Api.Fail.class,()->export.export(Map.of("rows",List.of(List.of("A"),List.of(1,2))),mock(HttpServletRequest.class)));}
 @Test void rendersEmptyReportWithZeroTotal()throws Exception{var export=new ExcelExport(mock(Api.class));try(var w=new XSSFWorkbook(new ByteArrayInputStream(export.export(Map.of("rows",List.of(List.of("Tên","Số tiền")),"totalColumns",List.of(1)),mock(HttpServletRequest.class)).getBody()))){assertEquals(0,w.getSheetAt(0).getRow(5).getCell(1).getNumericCellValue());}}
}
